// Waypoint graph for bots: nodes, edges, walkability validation, reachability and A* search.
import { PLAYER_RADIUS, STEP_HEIGHT } from './constants.js';
import { groundHeightAt, isBlocked } from './collision.js';

// Node definitions: id -> [x, z] or [x, z, y]. Names ending in "W" are west (site A side) and
// have an east twin with the "E" counterpart generated by mirroring x.
const MIRRORED_NODES = {
  TW: [-30, -70], TGW: [-46, -62],
  LN: [-48, -52], LM1: [-48, -42], LM2: [-48, -20], LM3: [-48, 12], LS: [-48, 30],
  SE1: [-44, 42], SE2: [-38, 52], SX: [-28, 52], SE3: [-27, 64], SITE: [-42, 75],
  MA: [-20, -42], GN: [-38, -42], MW2: [-18, -4], MW4: [-18, 12], G2: [-38, 12], MW5: [-18, 22],
  M6: [-8, 40], MS: [-10, 50], SH: [-24, 50], CTW: [-12, 75], CTG: [-24, 75],
  // Two-level middle: stair bottom/top, platform center and bridge end.
  STB: [-33, -4], STT: [-33, -14, 4], PC: [-32, -22, 4], BR: [-20, -22, 4],
};

const CENTER_NODES = {
  T0: [0, -72], TGM: [0, -62], M1: [0, -52], M3: [0, -30], MC: [0, 56], CTC: [0, 62], CT0: [0, 72],
  BR0: [0, -22, 4],
};

// Site A balcony stairs and site B balcony ramp do not mirror.
const UNIQUE_NODES = {
  AST0: [-53, 34, 0], AST1: [-53, 44, 4], ABAL: [-52, 54, 4],
  RB: [30, 59, 0], RT: [44, 59, 4], BBAL: [52, 53, 4],
};

// Chains of node ids; consecutive entries are connected. {S} is replaced by W/E suffixes.
const MIRRORED_CHAINS = [
  ['T0', 'TW', 'TGW', 'LN', 'LM1', 'LM2', 'LM3', 'LS', 'SE1', 'SE2', 'SX', 'SE3', 'SITE'],
  ['LM1', 'GN', 'MA', 'M1'],
  ['M3', 'MW2', 'MW4', 'MW5', 'M6', 'MS', 'MC'],
  ['LM3', 'G2', 'MW4'],
  ['MS', 'SH', 'SE2'],
  ['CT0', 'CTW', 'CTG', 'SITE'],
  ['MW2', 'STB', 'STT', 'PC', 'BR'],
];
const CENTER_CHAINS = [
  ['T0', 'TGM', 'M1', 'M3'],
  ['MC', 'CTC', 'CT0'],
  ['BRW', 'BR0', 'BRE'],
];
const UNIQUE_CHAINS = [
  ['LSW', 'AST0', 'AST1', 'ABAL'],
  ['SXE', 'RB', 'RT', 'BBAL'],
];

function suffix(id, side) {
  return `${id}${side}`;
}

function buildData() {
  const defs = new Map();
  for (const [id, v] of Object.entries(MIRRORED_NODES)) {
    defs.set(suffix(id, 'W'), v);
    defs.set(suffix(id, 'E'), [-v[0], ...v.slice(1)]);
  }
  for (const [id, v] of Object.entries(CENTER_NODES)) defs.set(id, v);
  for (const [id, v] of Object.entries(UNIQUE_NODES)) defs.set(id, v);

  const links = [];
  const chain = (ids) => {
    for (let i = 0; i + 1 < ids.length; i++) links.push([ids[i], ids[i + 1]]);
  };
  const mirroredNames = new Set(Object.keys(MIRRORED_NODES));
  const sideName = (id, side) => (mirroredNames.has(id) ? suffix(id, side) : id);
  for (const c of MIRRORED_CHAINS) {
    for (const side of ['W', 'E']) chain(c.map((id) => sideName(id, side)));
  }
  for (const c of CENTER_CHAINS) chain(c);
  for (const c of UNIQUE_CHAINS) chain(c);
  return { defs, links };
}

function buildGraph() {
  const { defs, links } = buildData();
  const nodes = [];
  const index = new Map();
  for (const [id, v] of defs) {
    index.set(id, nodes.length);
    nodes.push({ id, x: v[0], z: v[1], y: v[2] ?? 0 });
  }
  const adjacency = nodes.map(() => []);
  const seen = new Set();
  for (const [a, b] of links) {
    const ia = index.get(a);
    const ib = index.get(b);
    if (ia === undefined || ib === undefined) throw new Error(`waypoint link references unknown node ${a} -> ${b}`);
    const key = ia < ib ? `${ia}:${ib}` : `${ib}:${ia}`;
    if (seen.has(key)) continue;
    seen.add(key);
    const cost = Math.hypot(nodes[ia].x - nodes[ib].x, nodes[ia].y - nodes[ib].y, nodes[ia].z - nodes[ib].z);
    adjacency[ia].push({ to: ib, cost });
    adjacency[ib].push({ to: ia, cost });
  }
  return { nodes, adjacency, index };
}

export const WAYPOINTS = buildGraph();

export function getNode(graph, id) {
  const i = graph.index.get(id);
  return i === undefined ? null : graph.nodes[i];
}

/** Index of the node closest to a world position (ignores unreachable heights by weighting y). */
export function nearestWaypoint(graph, x, z, y = 0) {
  let best = -1;
  let bestD = Infinity;
  for (let i = 0; i < graph.nodes.length; i++) {
    const n = graph.nodes[i];
    const d = Math.hypot(n.x - x, n.z - z) + Math.abs(n.y - y) * 3;
    if (d < bestD) { bestD = d; best = i; }
  }
  return best;
}

/** Simulates walking from node a to node b and reports whether the body is never blocked. */
export function isEdgeWalkable(map, a, b, radius = PLAYER_RADIUS) {
  const dist = Math.hypot(b.x - a.x, b.z - a.z);
  const steps = Math.max(1, Math.ceil(dist / 0.2));
  let y = a.y;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const x = a.x + (b.x - a.x) * t;
    const z = a.z + (b.z - a.z) * t;
    if (isBlocked(map, x, y, z, radius)) return false;
    const g = groundHeightAt(map, x, z, y, radius);
    // A drop larger than a step would make the bot fall, which edges must not do.
    if (y - g > STEP_HEIGHT) return false;
    y = g;
  }
  return Math.abs(y - b.y) <= STEP_HEIGHT;
}

/** Lists edges that are not walkable (empty when the graph is consistent with the map). */
export function findBrokenEdges(map, graph) {
  const broken = [];
  for (let i = 0; i < graph.nodes.length; i++) {
    for (const e of graph.adjacency[i]) {
      if (e.to < i) continue;
      const a = graph.nodes[i];
      const b = graph.nodes[e.to];
      if (!isEdgeWalkable(map, a, b) || !isEdgeWalkable(map, b, a)) broken.push([a.id, b.id]);
    }
  }
  return broken;
}

/** Breadth-first set of node indexes reachable from start. */
export function reachableFrom(graph, start) {
  const visited = new Set([start]);
  const queue = [start];
  while (queue.length > 0) {
    const cur = queue.shift();
    for (const e of graph.adjacency[cur]) {
      if (!visited.has(e.to)) { visited.add(e.to); queue.push(e.to); }
    }
  }
  return visited;
}

export function isConnected(graph) {
  return graph.nodes.length === 0 || reachableFrom(graph, 0).size === graph.nodes.length;
}

/** A* search. Returns a list of node indexes from start to goal, or null when unreachable. */
export function findPath(graph, start, goal) {
  if (start === goal) return [start];
  const g = new Map([[start, 0]]);
  const parent = new Map();
  const open = [{ i: start, f: 0 }];
  const closed = new Set();
  const h = (i) => {
    const a = graph.nodes[i];
    const b = graph.nodes[goal];
    return Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z);
  };
  while (open.length > 0) {
    let bi = 0;
    for (let k = 1; k < open.length; k++) if (open[k].f < open[bi].f) bi = k;
    const { i: cur } = open.splice(bi, 1)[0];
    if (cur === goal) {
      const path = [cur];
      let p = cur;
      while (parent.has(p)) { p = parent.get(p); path.push(p); }
      return path.reverse();
    }
    if (closed.has(cur)) continue;
    closed.add(cur);
    for (const e of graph.adjacency[cur]) {
      const ng = g.get(cur) + e.cost;
      if (ng < (g.get(e.to) ?? Infinity)) {
        g.set(e.to, ng);
        parent.set(e.to, cur);
        open.push({ i: e.to, f: ng + h(e.to) });
      }
    }
  }
  return null;
}

/** Total length in meters of a path of node indexes. */
export function pathLength(graph, path) {
  let len = 0;
  for (let i = 0; i + 1 < path.length; i++) {
    const a = graph.nodes[path[i]];
    const b = graph.nodes[path[i + 1]];
    len += Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z);
  }
  return len;
}
